it('emits agent_end with accumulated usage when the stream completes', async () => {
  const agent = new Agent({
    name: 'StreamLifecycle',
    model: new SimpleStreamingModel({
      output: [fakeModelMessage('done')],
      usage: new Usage({
        requests: 1,
        inputTokens: 2,
        outputTokens: 3,
        totalTokens: 5,
      }),
    }),
  });
  const runner = new Runner();
  const agentEnd = vi.fn();
  const runnerEnd = vi.fn();
  let usageAtAgentEnd:
    | {
        requests: number;
        inputTokens: number;
        outputTokens: number;
        totalTokens: number;
      }
    | undefined;
  agent.on('agent_end', (context, output) => {
    usageAtAgentEnd = {
      requests: context.usage.requests,
      inputTokens: context.usage.inputTokens,
      outputTokens: context.usage.outputTokens,
      totalTokens: context.usage.totalTokens,
    };
    agentEnd(context, output);
  });
  runner.on('agent_end', runnerEnd);

  const result = await runner.run(agent, 'hi', { stream: true });
  await result.completed;

  expect(agentEnd).toHaveBeenCalledTimes(1);
  expect(agentEnd).toHaveBeenCalledWith(result.state._context, 'done');
  expect(runnerEnd).toHaveBeenCalledTimes(1);
  expect(runnerEnd).toHaveBeenCalledWith(
    result.state._context,
    agent,
    'done',
  );
  expect(usageAtAgentEnd).toMatchObject({
    requests: 1,
    inputTokens: 2,
    outputTokens: 3,
    totalTokens: 5,
  });
});

